/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600, tracking-tight. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

// gradients.sh "aurora": soft curtains over a near-black base, plus the
// horizontal band. Lives only inside the freed-time panel.
const BRAND_TAIL = /remocn$/i;

const AURORA = ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"];

function auroraFill(base: string, drift: number) {
  const n = AURORA.length;
  const curtains = AURORA.map((c, i) => {
    const x = 12 + (76 * i) / (n - 1) + Math.sin(drift + i * 1.9) * 4;
    const h = 150 + Math.cos(drift * 0.8 + i * 1.3) * 20;
    return `radial-gradient(34% ${h}% at ${x}% 100%, color-mix(in oklab, ${c} 80%, transparent) 0%, transparent 72%)`;
  });
  return [
    ...curtains,
    `linear-gradient(180deg, color-mix(in oklab, ${AURORA[0]} 18%, transparent) 0%, transparent 60%)`,
    base,
  ].join(", ");
}

interface TimeSegment {
  label: string;
  value: number;
}

interface TimeBreakdownProps {
  before?: TimeSegment[];
  after?: TimeSegment[];
  title?: string;
  beforeLabel?: string;
  afterLabel?: string;
  caption?: string;
  accent?: string;
  /** Text color of the labels and figures; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Schibsted Grotesk by default. */
  fontFamily?: string;
  /** Corner radius of the bar, in px at 720p. */
  radius?: number;
  /** Frames between characters of the hero figure as it rolls in. */
  stagger?: number;
  /** Replaces the remocn mark when `afterLabel` ends in "remocn". */
  logo?: React.ReactNode;
  grain?: boolean;
  /** Size of the chart, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

