function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Hero({
  text,
  t,
  size,
  color,
  fontFamily,
  stagger,
}: {
  text: string;
  t: number;
  size: number;
  color: string;
  fontFamily: string;
  stagger: number;
}) {
  return (
    <div
      style={{
        display: "flex",
        whiteSpace: "pre",
        fontFamily,
        fontWeight: 400,
        fontSize: size,
        lineHeight: 1,
        letterSpacing: "-0.045em",
        fontVariantNumeric: "tabular-nums",
        color,
      }}
    >
      {Array.from(text).map((ch, i) => {
        const p = interpolate(t, [i * stagger, i * stagger + 22], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingBottom: size * 0.06,
              marginBottom: -size * 0.06,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${(1 - p) * 0.7 * size}px)`,
                opacity: interpolate(p, [0, 0.4], [0, 1], CLAMP),
              }}
            >
              {ch}
            </span>
          </span>
        );
      })}
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function TimeBreakdownBase({
  before = DEFAULT_BEFORE,
  after = DEFAULT_AFTER,
  title = "Where the time goes",
  beforeLabel = "Before",
  afterLabel = "With remocn",
  caption = "less time per video",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  radius: corner = 12,
  stagger = 3,
  logo,
  grain = true,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: TimeBreakdownProps) {
  const glide = useGlide();
  const frame = useCurrentFrame();
  const t = Math.max(0, frame - delay) * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const th = THEMES[theme];
  const fg = ink ?? th.fg;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? th.bg);
  const clipId = `h${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const segs = before.slice(0, 5).map((b, i) => ({
    label: b.label,
    from: Math.max(0, b.value),
    to: Math.max(0, after[i]?.value ?? b.value),
  }));
  const totalBefore = segs.reduce((s, x) => s + x.from, 0) || 1;
  const totalAfter = segs.reduce((s, x) => s + x.to, 0);
  const saved = Math.max(0, Math.round((1 - totalAfter / totalBefore) * 100));
  const focus = segs.reduce(
    (best, s, i) =>
      s.from - s.to > segs[best].from - segs[best].to ? i : best,
    0,
  );

  const margin = width * 0.085;
  const x0 = margin;
  const barW = width - margin * 2;
  const barH = 84 * u;
  const barTop = height * 0.52;
  const radius = corner * u;

  const reveal = interpolate(t, [-4, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const split = interpolate(t, [T_SPLIT, T_SPLIT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gap = 6 * u * split;
  const sw = interpolate(t, [T_SWITCH, T_SWITCH + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const tint = interpolate(t, [T_COLLAPSE - 4, T_COLLAPSE + 6], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const c = interpolate(t, [T_COLLAPSE, T_DONE], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const usable = barW - gap * (segs.length - 1);
  const unitW = usable / totalBefore;
  const geom: { x: number; w: number; v: number }[] = [];
  let cursor = x0;
  segs.forEach((s) => {
    const v = s.from + (s.to - s.from) * c;
    const w = v * unitW;
    geom.push({ x: cursor, w, v });
    cursor += w + gap;
  });
  const usedEnd = cursor - gap;
  const freedX = usedEnd + gap;
  const freedW = Math.max(0, x0 + barW - freedX);
  const freedIn = interpolate(t, [T_COLLAPSE + 6, T_COLLAPSE + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const finalFreedX =
    x0 + segs.reduce((s, x) => s + x.to * unitW, 0) + 6 * u * segs.length;

  const labelEnds: number[] = [];
  const labelX = geom.map((g, i) => {
    const min = i > 0 ? labelEnds[i - 1] + 18 * u : g.x;
    const x = Math.max(g.x, min);
    // Schibsted Grotesk advances: ~0.53em lowercase at 18px, ~0.6em digits at 42px.
    const nameW = segs[i].label.length * 0.53 * 18 * u;
    const pctW =
      (String(Math.round((g.v / totalBefore) * 100)).length + 1) * 0.6 * 42 * u;
    labelEnds.push(x + Math.max(nameW, pctW));
    return x;
  });

  const heroT = t - (T_DONE - 4);
  const heroSize = Math.min(160 * u, width * 0.125);
  const capIn = interpolate(heroT, [12, 32], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const bracketIn = interpolate(heroT, [-6, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const titleIn = interpolate(t, [-6, 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const driftAt = (f: number) =>
    interpolate(Math.max(0, f - delay) * speed, [0, T_DONE + 60], [1.025, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const drift = driftAt(frame);
  // The drift's ease is so flat at its ends that a progress test would keep
  // the tilt on while nothing visibly moves; weigh the scale step by the
  // distance from the origin to the frame's edge instead.
  const reach = Math.max(width, height) / 2;
  const drifting =
    Math.abs(driftAt(frame + 1) - drift) * reach > 1e-3 ||
    Math.abs(drift - driftAt(frame - 1)) * reach > 1e-3;

  const bracketY = barTop - 22 * u;
  const auroraDrift = interpolate(
    t,
    [T_COLLAPSE, T_DONE + 80],
    [0, 1.6],
    CLAMP,
  );
  const tick = 8 * u;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 70% at 40% 45%, ${th.stage}, transparent 75%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${drift})${glide(drifting)}`,
            transformOrigin: "50% 55%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: x0,
              top: height * 0.2,
              fontFamily,
              fontSize: 22 * u,
              fontWeight: 500,
              color: th.muted,
              whiteSpace: "nowrap",
              opacity: titleIn,
              transform: `translateY(${(1 - titleIn) * 8 * u}px)`,
            }}
          >
            {title}
          </div>

          <div
            style={{
              position: "absolute",
              left: x0,
              top: barTop - 70 * u,
              width: barW * 0.45,
              height: 40 * u,
              opacity: titleIn,
            }}
          >
            {[beforeLabel, afterLabel].map((lbl, i) => {
              const a =
                i === 0
                  ? interpolate(sw, [0, 0.6], [1, 0], CLAMP)
                  : interpolate(sw, [0.35, 1], [0, 1], CLAMP);
              const y = i === 0 ? -sw * 14 * u : (1 - sw) * 14 * u;
              return (
                <div
                  key={lbl}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    height: 40 * u,
                    display: "flex",
                    alignItems: "center",
                    gap: 10 * u,
                    opacity: a,
                    transform: `translateY(${y}px)`,
                    filter: a < 0.98 ? `blur(${(1 - a) * 4 * u}px)` : undefined,
                    fontFamily,
                    fontSize: 30 * u,
                    fontWeight: 400,
                    letterSpacing: "-0.025em",
                    color: fg,
                    whiteSpace: "nowrap",
                  }}
                >
                  {i === 1 && BRAND_TAIL.test(lbl) ? (
                    <>
                      {lbl.replace(BRAND_TAIL, "").trim()}
                      <span style={{ marginLeft: 2 * u, marginTop: 2 * u }}>
                        {logo ?? <RemocnLogo fontSize={31 * u} color={fg} />}
                      </span>
                    </>
                  ) : (
                    <>
                      {i === 1 ? (
                        <span
                          style={{
                            width: 10 * u,
                            height: 10 * u,
                            borderRadius: "50%",
                            background: accent,
                          }}
                        />
                      ) : null}
                      {lbl}
                    </>
                  )}
                </div>
              );
            })}
          </div>

          {freedW > 1 ? (
            <div
              style={{
                position: "absolute",
                left: freedX,
                top: barTop,
                width: freedW,
                height: barH,
                borderRadius: radius,
                overflow: "hidden",
                opacity: freedIn,
                background: auroraFill(th.aurora, auroraDrift),
                boxShadow: `inset 0 0 0 ${Math.max(1, u)}px ${th.auroraEdge}`,
              }}
            />
          ) : null}

          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            aria-hidden
          >
            <defs>
              <clipPath id={`${clipId}c`}>
                <rect
                  x={x0}
                  y={barTop - 4 * u}
                  width={barW * reveal}
                  height={barH + 8 * u}
                />
              </clipPath>
            </defs>

            <g clipPath={`url(#${clipId}c)`}>
              {geom.map((g, i) => {
                const tone = th.tones[Math.min(i, th.tones.length - 1)];
                const split3 = interpolateColors(
                  split,
                  [0, 1],
                  [th.base, tone],
                );
                const fill =
                  i === focus
                    ? interpolateColors(tint, [0, 1], [split3, accent])
                    : split3;
                const first = i === 0;
                const last = i === geom.length - 1;
                const rl = first ? radius : radius * split * 0.35;
                const rr = last ? radius : radius * split * 0.35;
                const w = Math.max(g.w, 2 * u);
                const rlc = Math.min(rl, w / 2);
                const rrc = Math.min(rr, w / 2);
                const x = g.x;
                const y = barTop;
                const h = barH;
                const d = [
                  `M ${x + rlc} ${y}`,
                  `H ${x + w - rrc}`,
                  `Q ${x + w} ${y} ${x + w} ${y + rrc}`,
                  `V ${y + h - rrc}`,
                  `Q ${x + w} ${y + h} ${x + w - rrc} ${y + h}`,
                  `H ${x + rlc}`,
                  `Q ${x} ${y + h} ${x} ${y + h - rlc}`,
                  `V ${y + rlc}`,
                  `Q ${x} ${y} ${x + rlc} ${y}`,
                  "Z",
                ].join(" ");
                return <path key={segs[i].label} d={d} fill={fill} />;
              })}
            </g>

            {saved > 0 ? (
              <g
                opacity={bracketIn}
                stroke={th.hair}
                strokeWidth={Math.max(1, 1.25 * u)}
              >
                <line
                  x1={finalFreedX}
                  x2={finalFreedX + (x0 + barW - finalFreedX) * bracketIn}
                  y1={bracketY}
                  y2={bracketY}
                />
                <line
                  x1={finalFreedX}
                  x2={finalFreedX}
                  y1={bracketY - tick}
                  y2={bracketY + tick}
                />
                <line
                  x1={x0 + barW}
                  x2={x0 + barW}
                  y1={bracketY - tick}
                  y2={bracketY + tick}
                  opacity={interpolate(bracketIn, [0.85, 1], [0, 1], CLAMP)}
                />
              </g>
            ) : null}
          </svg>

          {geom.map((g, i) => {
            const a = interpolate(
              t,
              [T_SPLIT + 6 + i * 4, T_SPLIT + 26 + i * 4],
              [0, 1],
              {
                ...CLAMP,
                easing: EASE_OUT,
              },
            );
            const countIn = interpolate(
              t,
              [T_SPLIT + 6 + i * 4, T_SPLIT + 34 + i * 4],
              [0, 1],
              { ...CLAMP, easing: Easing.bezier(0.22, 1, 0.36, 1) },
            );
            const isFocus = i === focus;
            const pct = Math.round((g.v / totalBefore) * 100 * countIn);
            return (
              <div
                key={segs[i].label}
                style={{
                  position: "absolute",
                  left: labelX[i],
                  top: barTop + barH + 20 * u,
                  display: "flex",
                  flexDirection: "column",
                  gap: 2 * u,
                  opacity: a,
                  transform: `translateY(${(1 - a) * 10 * u}px)`,
                  whiteSpace: "nowrap",
                }}
              >
                <span
                  style={{
                    fontFamily,
                    fontSize: 18 * u,
                    fontWeight: 500,
                    color: isFocus
                      ? interpolateColors(tint, [0, 1], [th.muted, accent])
                      : th.muted,
                  }}
                >
                  {segs[i].label}
                </span>
                <span
                  style={{
                    fontFamily,
                    fontSize: 42 * u,
                    fontWeight: 400,
                    letterSpacing: "-0.035em",
                    fontVariantNumeric: "tabular-nums",
                    color: fg,
                  }}
                >
                  {pct}%
                </span>
              </div>
            );
          })}

          {saved > 0 ? (
            <div
              style={{
                position: "absolute",
                left: finalFreedX - heroSize * 0.04,
                top: bracketY - 22 * u,
                transform: "translateY(-100%)",
                display: "flex",
                alignItems: "baseline",
                gap: 18 * u,
              }}
            >
              <Hero
                text={`${saved}%`}
                t={heroT}
                size={heroSize}
                color={fg}
                fontFamily={fontFamily}
                stagger={stagger}
              />
              <span
                style={{
                  fontFamily,
                  fontSize: 32 * u,
                  fontWeight: 400,
                  letterSpacing: "-0.02em",
                  color: th.muted,
                  whiteSpace: "nowrap",
                  opacity: capIn,
                  transform: `translateY(${(1 - capIn) * 10 * u}px)`,
                }}
              >
                {caption}
              </span>
            </div>
          ) : null}
        </AbsoluteFill>
      </ScaleLayer>

      {transparent ? null : (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 60%, ${stage} 100%)`,
            opacity: 0.55,
          }}
        />
      )}
      {grain ? <Grain opacity={th.grain} /> : null}
    </AbsoluteFill>
  );
}

