const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","beforeLabel","afterLabel","caption","radius","stagger","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "Where the time goes",
  beforeLabel: "Before",
  afterLabel: "With remocn",
  caption: "less time per video",
  radius: 12,
  stagger: 3,
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TimeBreakdownElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TimeBreakdownBase>;

const TimeBreakdownInner = forwardRef<
  HTMLDivElement,
  TimeBreakdownElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TimeBreakdown>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TimeBreakdownBase
          {...(componentProps as unknown as ComponentProps<typeof TimeBreakdownBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TimeBreakdown = Interactive.withSchema({
  Component: TimeBreakdownInner,
  componentName: "<TimeBreakdown>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
